import { useCallback, useEffect, useRef } from 'react';
import type { RefObject } from 'react';

interface ScrollPosition {
  readonly left: number;
  readonly top: number;
}

// Chromium centers a card that Tab or Shift+Tab focuses inside the board before focus handlers
// run. Scroll events arrive a frame later, so the last board position they reported still shows
// the view from before that scroll. Restoring it first lets the card scroll from where the player
// was looking, with nearest alignment in the board. The page scroll is left to the browser.
export function useNearestScroll(viewport: RefObject<HTMLElement | null>) {
  const board = useRef<ScrollPosition>({ left: 0, top: 0 });
  useEffect(() => {
    const element = viewport.current;
    function boardScrolled(): void {
      if (element) board.current = { left: element.scrollLeft, top: element.scrollTop };
    }
    boardScrolled();
    element?.addEventListener('scroll', boardScrolled, { passive: true });
    return () => element?.removeEventListener('scroll', boardScrolled);
  }, [viewport]);

  return useCallback(
    (card: HTMLElement): void => {
      viewport.current?.scrollTo(board.current.left, board.current.top);
      card.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    },
    [viewport],
  );
}
import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { ReproductionControl } from '../src/game/controls/control-labels.ts';
import { SelectionKind } from '../src/game/selection.ts';
import { SNAPSHOT_VERSION } from '../src/game/snapshot.ts';
import { exportedSnapshot, loadTimedBoard } from './game-fixture.ts';
import { uiSnapshot } from './ui-snapshot.ts';

const REMAINING_MS = 300;

async function loadDraft(
  page: Parameters<typeof loadTimedBoard>[0],
  snapshot: unknown,
): Promise<void> {
  await page.locator('summary').click();
  await page
    .getByLabel(ReproductionControl.snapshot, { exact: true })
    .fill(JSON.stringify(snapshot));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await page.locator('summary').click();
}

test('Resume focuses the remembered card before removal and continues the exact remaining interval', async ({
  page,
}) => {
  await loadTimedBoard(page);
  const snapshot = {
    version: SNAPSHOT_VERSION,
    boardCode: EXAMPLE_CODE,
    matched: [],
    moves: 1,
    elapsedMs: 500,
    started: true,
    selection: { kind: SelectionKind.mismatch, first: 0, second: 1, remainingMs: REMAINING_MS },
  };
  await loadDraft(page, snapshot);
  await page.locator('.card').nth(2).click();
  await page.keyboard.press('Enter');
  await page.keyboard.press('ArrowRight');
  await expect(page.locator('.card').nth(3)).toBeFocused();
  await page.clock.runFor(2000);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  expect((await exportedSnapshot(page)).elapsedMs).toBe(snapshot.elapsedMs);
  await page.getByRole('button', { name: ReproductionControl.resume, exact: true }).click();
  await expect(page.locator('.card').nth(3)).toBeFocused();
  await page.clock.runFor(REMAINING_MS - 1);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await expect(page.locator('.card.closed')).toHaveCount(16);
});

test('invalid drafts keep the current game and a loaded win changes neither best nor celebration', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(2).click();
  await page.locator('.card').nth(6).click();
  await page.locator('.card').nth(0).click();
  await page.clock.runFor(1200);
  const original = await exportedSnapshot(page);
  await page.locator('summary').click();
  const code = page.getByLabel(ReproductionControl.board, { exact: true });
  const invalidCode = 'invalid';
  await code.fill(invalidCode);
  await page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true }).click();
  expect(await code.inputValue()).toBe(invalidCode);
  const field = page.getByLabel(ReproductionControl.snapshot, { exact: true });
  const invalidSnapshot = '{';
  await field.fill(invalidSnapshot);
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  expect(await field.inputValue()).toBe(invalidSnapshot);
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toEqual(original);
  await loadDraft(page, {
    version: SNAPSHOT_VERSION,
    boardCode: EXAMPLE_CODE,
    matched: EXAMPLE_PAIRS.flat(),
    selection: { kind: SelectionKind.closed },
    moves: EXAMPLE_PAIRS.length,
    elapsedMs: 500,
    started: true,
  });
  await expect(page.locator('.card.matched')).toHaveCount(16);
  expect(await page.locator('.victory.celebrate').count()).toBe(0);
  const expected = await uiSnapshot();
  await expect(page.locator('.stats dd').nth(3)).toHaveText(expected.bestNone);
  await expect(
    page.getByRole('button', { name: ReproductionControl.resume, exact: true }),
  ).toHaveCount(0);
  await expect(page.getByRole('status')).toHaveText('Loaded completed snapshot.');
  await page.clock.runFor(1000);
  expect((await exportedSnapshot(page)).elapsedMs).toBe(500);
  await expect(page.locator('.card.matched')).toHaveCount(16);
  expect(await page.locator('.victory.celebrate').count()).toBe(0);
});
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { test } from 'vitest';
import { sourceFiles } from './source-files.ts';
import { isJsonObject } from '../src/game/saved-format.ts';

test('packages and lock use the reviewed exact versions and strict separate compiler projects', async () => {
  const pkg: unknown = JSON.parse(await readFile('package.json', 'utf8'));
  const expected: unknown = JSON.parse(
    await readFile(new URL('./package.fixture.json', import.meta.url), 'utf8'),
  );
  assert.ok(
    isJsonObject(pkg) &&
      isJsonObject(pkg.dependencies) &&
      isJsonObject(pkg.devDependencies) &&
      isJsonObject(expected),
  );
  const installed = { ...pkg.dependencies, ...pkg.devDependencies };
  assert.deepEqual(Object.keys(pkg.dependencies).sort(), ['react', 'react-dom']);
  for (const [name, version] of Object.entries(expected)) assert.equal(installed[name], version);
  const lock: unknown = JSON.parse(await readFile('package-lock.json', 'utf8'));
  assert.ok(isJsonObject(lock) && isJsonObject(lock.packages));
  const locked = lock.packages[''];
  assert.ok(isJsonObject(locked));
  assert.deepEqual(locked.dependencies, pkg.dependencies);
  assert.deepEqual(locked.devDependencies, pkg.devDependencies);
  assert.equal(pkg.type, 'module');
  const config: unknown = JSON.parse(await readFile('tsconfig.base.json', 'utf8'));
  assert.ok(isJsonObject(config) && isJsonObject(config.compilerOptions));
  for (const key of [
    'strict',
    'noUncheckedIndexedAccess',
    'exactOptionalPropertyTypes',
    'verbatimModuleSyntax',
    'erasableSyntaxOnly',
  ])
    assert.equal(config.compilerOptions[key], true);
  for (const project of ['app', 'node', 'e2e'])
    assert.ok(await readFile(`tsconfig.${project}.json`, 'utf8'));
  assert.ok(isJsonObject(pkg.scripts));
  assert.equal(
    pkg.scripts.typecheck,
    'tsc -p tsconfig.app.json && tsc -p tsconfig.node.json && tsc -p tsconfig.e2e.json',
    'T07 every compiler project',
  );
  assert.equal(pkg.scripts.test, 'vitest run', 'T02 Vitest runs unit tests');
});

test('authored TypeScript stays small, uses static ESM and rejects unsafe type escapes', async () => {
  const files = (await Promise.all(['src', 'scripts', 'tests', 'art'].map(sourceFiles))).flat();
  for (const file of files.filter((file) => /\.tsx?$/.test(file.path))) {
    assert.ok(file.text.trimEnd().split(/\r?\n/).length <= 200, file.path);
    assert.doesNotMatch(file.text, /@ts-(?:ignore|nocheck|expect-error)/);
    assert.doesNotMatch(
      file.text,
      /\bany\b|\bas\s+(?:[A-Z{]|unknown\b|number\b|string\b)|\bimport\s*\(|\brequire\s*\(/,
    );
  }
});

test('the game core has no browser effects and the shipped source has no audio or diagnostic entry', async () => {
  const files = await sourceFiles('src');
  const core = new Set(['deck.ts', 'game.ts', 'snapshot.ts', 'snapshot-selection.ts', 'replay.ts']);
  for (const file of files.filter((file) => !/\.(test|fixture)\./.test(file.path))) {
    assert.doesNotMatch(
      file.text,
      /AudioContext|new Audio\b|<audio|<canvas|fetch\(|XMLHttpRequest|window\.[a-zA-Z]*[Dd]eck/,
    );
    if (core.has(file.path.split(/[\\/]/).at(-1) ?? ''))
      assert.doesNotMatch(
        file.text,
        /\b(window|document|localStorage|performance|crypto|Date)\b|Math\.random/,
      );
    assert.doesNotMatch(file.text, /fixture|face-sheet|test-results/);
  }
});
